package io.beep.core.adapter.out.postgres;
import io.beep.core.app.port.EnterpriseRepository;
import io.beep.core.domain.DomainException;
import java.time.*;
import java.util.*;
import org.jooq.DSLContext;
import org.jooq.JSONB;
public class PostgresEnterpriseAdapter implements EnterpriseRepository {
 private final DSLContext db;
 public PostgresEnterpriseAdapter(DSLContext db){this.db=db;}
 private static OffsetDateTime at(Instant t){return t.atOffset(ZoneOffset.UTC);}
 private List<Map<String,Object>> rows(String sql,Object...args){return db.fetch("SELECT to_jsonb(q) AS data FROM ("+sql+") q",args).map(r->Sql.map(r.get("data",JSONB.class)));}
 private static String json(Object o){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException(e);}}
 @Override public Optional<Map<String,Object>> contract(UUID w){return rows("SELECT workspace_id AS \"workspaceId\",version,reference,status,starts_at AS \"startsAt\",ends_at AS \"endsAt\",sla_bp AS \"slaBp\",dpa_reference AS \"dpaReference\",dpa_sha256 AS \"dpaSha256\",retention_days AS \"retentionDays\",ip_allowlist AS \"ipAllowlist\",brand_name AS \"brandName\",brand_color AS \"brandColor\",sso,updated_at AS \"updatedAt\" FROM enterprise_contracts WHERE workspace_id=?",w).stream().findFirst();}
 @Override public String ssoSecret(UUID w){return db.fetchSingle("SELECT sso_secret_cipher FROM enterprise_contracts WHERE workspace_id=?",w).get(0,String.class);}
 @Override public void saveContract(UUID w,Map<String,Object> c,Map<String,Object> sso,String secret,UUID staff,Instant now){
  if(db.fetchOptional("SELECT id FROM workspaces WHERE id=? FOR UPDATE",w).isEmpty())throw new DomainException("not_found");
  int version=((Number)c.get("version")).intValue();var old=contract(w);if(version!=(old.isEmpty()?1:((Number)old.get().get("version")).intValue()+1))throw new DomainException("conflict");
  db.execute("INSERT INTO enterprise_contracts(workspace_id,version,reference,status,starts_at,ends_at,sla_bp,dpa_reference,dpa_sha256,retention_days,ip_allowlist,brand_name,brand_color,sso,sso_secret_cipher,updated_by,updated_at) VALUES(?,?,?,?,?::timestamptz,?::timestamptz,?,?,?,?,?::jsonb,?,?,?::jsonb,?,?,?::timestamptz) ON CONFLICT(workspace_id) DO UPDATE SET version=excluded.version,reference=excluded.reference,status=excluded.status,starts_at=excluded.starts_at,ends_at=excluded.ends_at,sla_bp=excluded.sla_bp,dpa_reference=excluded.dpa_reference,dpa_sha256=excluded.dpa_sha256,retention_days=excluded.retention_days,ip_allowlist=excluded.ip_allowlist,brand_name=excluded.brand_name,brand_color=excluded.brand_color,sso=excluded.sso,sso_secret_cipher=excluded.sso_secret_cipher,updated_by=excluded.updated_by,updated_at=excluded.updated_at",w,version,c.get("reference"),c.get("status"),c.get("startsAt"),c.get("endsAt"),c.get("slaBp"),c.get("dpaReference"),c.get("dpaSha256"),c.get("retentionDays"),json(c.get("ipAllowlist")),c.get("brandName"),c.get("brandColor"),json(sso),secret,staff,at(now));
  db.execute("DELETE FROM enterprise_sso_states WHERE workspace_id=?",w);db.execute("DELETE FROM enterprise_sso_pending WHERE workspace_id=?",w);
 }
 @Override public Map<String,Object> overview(Instant now){return Map.of("nodes",rows("SELECT id,role,region,heartbeat_at,heartbeat_at>?::timestamptz AS healthy,capacity FROM platform_nodes ORDER BY id",at(now.minusSeconds(90))),"database",rows("SELECT pg_is_in_recovery() AS replica,pg_database_size(current_database()) AS bytes,(SELECT count(*) FROM pg_stat_activity WHERE datname=current_database()) AS connections,(SELECT setting::int FROM pg_settings WHERE name='max_connections') AS max_connections,CASE WHEN pg_is_in_recovery() AND pg_last_xact_replay_timestamp() IS NOT NULL THEN greatest(0,extract(epoch FROM now()-pg_last_xact_replay_timestamp())) END AS replay_age_seconds"),"replication",rows("SELECT application_name,state,sync_state,write_lag::text,flush_lag::text,replay_lag::text FROM pg_stat_replication"),"contracts",rows("SELECT workspace_id,reference,status,version,ends_at,sla_bp FROM enterprise_contracts ORDER BY updated_at DESC LIMIT 200"),"sdk",rows("SELECT * FROM sdk_releases ORDER BY published_at DESC LIMIT 100"),"evidence",rows("SELECT *,expires_at>?::timestamptz AS current FROM compliance_evidence ORDER BY collected_at DESC LIMIT 200",at(now)),"reviews",rows("SELECT *,due_at<=?::timestamptz AS overdue FROM access_reviews ORDER BY reviewed_at DESC LIMIT 200",at(now)),"failovers",rows("SELECT * FROM assisted_failovers ORDER BY created_at DESC LIMIT 100"));}
 @Override public void evidence(Map<String,Object>b,UUID staff,Instant now){db.execute("INSERT INTO compliance_evidence VALUES(?,?,?,?,?,?,?::timestamptz,?::timestamptz)",UUID.randomUUID(),b.get("framework"),b.get("control"),b.get("url"),b.get("sha256"),staff,at(now),b.get("expiresAt"));}
 @Override public void sdk(Map<String,Object>b,UUID staff,Instant now){db.execute("INSERT INTO sdk_releases VALUES(?,?,?,?,?,?,?,?::timestamptz) ON CONFLICT(platform,version) DO UPDATE SET status=excluded.status,minimum_version=excluded.minimum_version,published_by=excluded.published_by,published_at=excluded.published_at WHERE sdk_releases.url=excluded.url AND sdk_releases.sha256=excluded.sha256",b.get("platform"),b.get("version"),b.get("url"),b.get("sha256"),b.get("status"),b.get("minimumVersion"),staff,at(now));var r=db.fetchSingle("SELECT url,sha256 FROM sdk_releases WHERE platform=? AND version=?",b.get("platform"),b.get("version"));if(!Objects.equals(r.get(0),b.get("url"))||!Objects.equals(r.get(1),b.get("sha256")))throw new DomainException("conflict");}
 @Override public void review(UUID w,String decision,String reason,UUID staff,Instant now){if(w==null)throw new DomainException("invalid_request");if(db.fetchOptional("SELECT id FROM workspaces WHERE id=?",w).isEmpty())throw new DomainException("not_found");var snapshot=rows("SELECT owner_id AS user_id,'owner' AS role FROM workspaces WHERE id=? UNION ALL SELECT user_id,role FROM workspace_members WHERE workspace_id=? ORDER BY user_id",w,w);db.execute("INSERT INTO access_reviews VALUES(?,?,?,?::jsonb,?,?,?::timestamptz,?::timestamptz)",UUID.randomUUID(),w,staff,json(snapshot),decision,reason,at(now),at(now.plus(Duration.ofDays(90))));}
 @Override public Map<String,Object> failover(String node,UUID request,String action,String reason,UUID staff,Instant now){if(action.equals("request")){if(db.fetchOptional("SELECT id FROM platform_nodes WHERE id=? AND heartbeat_at<=?::timestamptz",node,at(now.minusSeconds(90))).isEmpty())throw new DomainException("conflict");UUID id=UUID.randomUUID();try{db.execute("INSERT INTO assisted_failovers(id,node_id,requested_by,reason,created_at) VALUES(?,?,?,?,?::timestamptz)",id,node,staff,reason,at(now));}catch(RuntimeException e){if(Sql.hasState(e,"23505"))throw new DomainException("conflict");throw e;}return Map.of("id",id,"status","requested","automatic",false);}int n=db.execute("UPDATE assisted_failovers SET status=?,confirmed_at=?::timestamptz WHERE id=? AND status='requested'",action.equals("confirm")?"confirmed":"cancelled",at(now),request);if(n!=1)throw new DomainException("conflict");return Map.of("status",action.equals("confirm")?"confirmed":"cancelled","automatic",false);}
 @Override public void heartbeat(String id,String role,String region,Map<String,Object> capacity,Instant now){db.execute("INSERT INTO platform_nodes VALUES(?,?,?,?::timestamptz,?::jsonb) ON CONFLICT(id) DO UPDATE SET role=excluded.role,region=excluded.region,heartbeat_at=excluded.heartbeat_at,capacity=excluded.capacity",id,role,region,at(now),json(capacity));}
 @Override public void state(String hash,UUID w,int version,String verifier,String nonce,Instant expiry){db.execute("INSERT INTO enterprise_sso_states VALUES(?,?,?,?,?,?::timestamptz)",hash,w,version,verifier,nonce,at(expiry));}
 @Override public Optional<Map<String,Object>> consumeState(String hash,Instant now){return db.fetchOptional("DELETE FROM enterprise_sso_states WHERE state_hash=? AND expires_at>?::timestamptz RETURNING workspace_id,version,verifier_cipher,nonce",hash,at(now)).map(r->Map.of("workspace",r.get("workspace_id",UUID.class),"version",r.get("version",Integer.class),"verifier",r.get("verifier_cipher",String.class),"nonce",r.get("nonce",String.class)));}
 @Override public Optional<UUID> identity(UUID w,String issuer,String subject){return db.fetchOptional("SELECT user_id FROM enterprise_sso_identities WHERE workspace_id=? AND issuer=? AND subject=?",w,issuer,subject).map(r->r.get(0,UUID.class));}
 @Override public void bindIdentity(UUID w,String issuer,String subject,UUID user){db.execute("INSERT INTO enterprise_sso_identities VALUES(?,?,?,?) ON CONFLICT DO NOTHING",w,issuer,subject,user);if(!identity(w,issuer,subject).filter(user::equals).isPresent())throw new DomainException("forbidden");}
 @Override public void proof(String hash,UUID w,int version){db.execute("INSERT INTO enterprise_sso_sessions VALUES(?,?,?) ON CONFLICT(session_hash,workspace_id) DO UPDATE SET version=excluded.version",hash,w,version);}
 @Override public boolean hasProof(String hash,UUID w,int version){return hash!=null&&db.fetchOptional("SELECT 1 FROM enterprise_sso_sessions WHERE session_hash=? AND workspace_id=? AND version=?",hash,w,version).isPresent();}
 @Override public void pendingProof(String hash,UUID w,int version,Instant expiry){db.execute("INSERT INTO enterprise_sso_pending VALUES(?,?,?,?::timestamptz)",hash,w,version,at(expiry));}
 @Override public void completeProof(String hash,String session,Instant now){db.fetchOptional("DELETE FROM enterprise_sso_pending WHERE mfa_hash=? AND expires_at>?::timestamptz RETURNING workspace_id,version",hash,at(now)).ifPresent(r->proof(session,r.get("workspace_id",UUID.class),r.get("version",Integer.class)));}
 @Override public List<Map<String,Object>> apps(UUID w){return rows("SELECT id,name,scheme,android_store AS \"androidStore\",ios_store AS \"iosStore\",enabled FROM mobile_apps WHERE workspace_id=? ORDER BY created_at",w);}
 @Override public void app(UUID w,Map<String,Object>b,Instant now){if(((Number)db.fetchValue("SELECT count(*) FROM mobile_apps WHERE workspace_id=? AND enabled",w)).intValue()>=50)throw new DomainException("quota_reached");db.execute("INSERT INTO mobile_apps VALUES(?,?,?,?,?,?,true,?::timestamptz)",b.get("id"),w,b.get("name"),b.get("scheme"),b.get("androidStore"),b.get("iosStore"),at(now));}
 @Override public void disableApp(UUID w,UUID id){if(db.execute("UPDATE mobile_apps SET enabled=false WHERE id=? AND workspace_id=?",id,w)!=1)throw new DomainException("not_found");db.execute("DELETE FROM deferred_tokens WHERE app_id=?",id);}
 @Override public Optional<Map<String,Object>> app(UUID id){return rows("SELECT id,workspace_id AS \"workspaceId\",name,scheme,android_store AS \"androidStore\",ios_store AS \"iosStore\",enabled FROM mobile_apps WHERE id=?",id).stream().findFirst();}
 @Override public void deferred(String hash,UUID app,String cipher,String platform,Instant now,Instant expires){db.execute("INSERT INTO deferred_tokens VALUES(?,?,?,?,?::timestamptz,?::timestamptz)",hash,app,cipher,platform,at(expires),at(now));}
 @Override public Optional<String> consumeDeferred(String hash,UUID app,String platform,Instant now){return db.fetchOptional("DELETE FROM deferred_tokens WHERE token_hash=? AND app_id=? AND platform=? AND expires_at>?::timestamptz RETURNING payload_cipher",hash,app,platform,at(now)).map(r->r.get(0,String.class));}
 @Override public void retention(Instant now){for(String table:List.of("deferred_tokens","enterprise_sso_states","enterprise_sso_pending"))db.execute("DELETE FROM "+table+" WHERE expires_at<=?::timestamptz",at(now));db.execute("DELETE FROM shared_rate_limits WHERE expires_at<=?::timestamptz",at(now));db.execute("DELETE FROM platform_nodes WHERE heartbeat_at<?::timestamptz",at(now.minus(Duration.ofDays(30))));}
}
